var g=UnityEngine.GameObject.Find("ThuyKieu");
return new {renderers=g.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>().Select(r=>new{r.name,r.sharedMesh.vertexCount,bounds=r.bounds.ToString(),materials=r.sharedMaterials.Select(m=>new{m.name,path=UnityEditor.AssetDatabase.GetAssetPath(m),shader=m.shader.name,texture=m.mainTexture==null?null:UnityEditor.AssetDatabase.GetAssetPath(m.mainTexture)}).ToArray()}).ToArray(),materials=UnityEditor.AssetDatabase.FindAssets("t:Material",new[]{"Assets/_Game/Art/Characters/ThuyKieu"}).Select(UnityEditor.AssetDatabase.GUIDToAssetPath).Select(p=>{var m=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>(p);return new{p,m.name,shader=m.shader.name,texture=m.mainTexture==null?null:UnityEditor.AssetDatabase.GetAssetPath(m.mainTexture)};}).ToArray()};
